"use strict";(self.webpackChunkdocusaurus_example=self.webpackChunkdocusaurus_example||[]).push([[7997],{3742:(e,a,s)=>{s.d(a,{A:()=>o});const o=s.p+"assets/images/makefiles-bash-b94f519b8e53a0bba9aef6d4b5bb7292.png"},6481:(e,a,s)=>{s.r(a),s.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>d});const o=JSON.parse('{"id":"bash/estandarizacion-makefiles","title":"Estandarizaci\xf3n autom\xe1tica de Makefiles CSM para compilaci\xf3n global de entorno legacy en Mainframe HPE","description":"Este fue un proyecto ambicioso de car\xe1cter privada, raz\xf3n por la cual no puedo sino solo mostrar conceptualmente en qu\xe9 consisti\xf3. Los equipos mainframe de HP tienen caracter\xedsticas especiales: sistema operativo y de archivos propietarios, arquitectura de hardware espec\xedfica, entre otras. Estas especificaciones ocasionan que piezas y herramientas de software de uso frecuente no sean compatibles en estos equipos. A este contexto se le suman dificultades a\xf1adidas por utilizar soluciones y ecosistemas monol\xedticos, acompa\xf1ados de un sistema de control de versi\xf3n tercerizado, mezcla entre gestor de despliegues y control de fuentes no est\xe1ndar, dise\xf1ado para trabajar con HPE. Se utilizaba una metodolog\xeda tradicional de desarrollo de software, en cascada. Ante la demanda creciente de desarrollo y arreglos de software, cada pieza del monolito se compilaba y desplegaba en forma independiente. Esto ocasionaba un riesgo alt\xedsimo por falta de acoplamiento o incompatibilidad entre desarrollos, e incluso supresi\xf3n involuntaria de versiones.","source":"@site/docs/bash/estandarizacion-makefiles.md","sourceDirName":"bash","slug":"/bash/estandarizacion-makefiles","permalink":"/business-card/docs/bash/estandarizacion-makefiles","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1},"sidebar":"bashSidebar"}');var i=s(4848),n=s(8453);const r={sidebar_position:1},t="Estandarizaci\xf3n autom\xe1tica de Makefiles CSM para compilaci\xf3n global de entorno legacy en Mainframe HPE",c={},d=[];function l(e){const a={h1:"h1",header:"header",img:"img",p:"p",...(0,n.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"estandarizaci\xf3n-autom\xe1tica-de-makefiles-csm-para-compilaci\xf3n-global-de-entorno-legacy-en-mainframe-hpe",children:"Estandarizaci\xf3n autom\xe1tica de Makefiles CSM para compilaci\xf3n global de entorno legacy en Mainframe HPE"})}),"\n",(0,i.jsx)(a.p,{children:"Este fue un proyecto ambicioso de car\xe1cter privada, raz\xf3n por la cual no puedo sino solo mostrar conceptualmente en qu\xe9 consisti\xf3. Los equipos mainframe de HP tienen caracter\xedsticas especiales: sistema operativo y de archivos propietarios, arquitectura de hardware espec\xedfica, entre otras. Estas especificaciones ocasionan que piezas y herramientas de software de uso frecuente no sean compatibles en estos equipos. A este contexto se le suman dificultades a\xf1adidas por utilizar soluciones y ecosistemas monol\xedticos, acompa\xf1ados de un sistema de control de versi\xf3n tercerizado, mezcla entre gestor de despliegues y control de fuentes no est\xe1ndar, dise\xf1ado para trabajar con HPE. Se utilizaba una metodolog\xeda tradicional de desarrollo de software, en cascada. Ante la demanda creciente de desarrollo y arreglos de software, cada pieza del monolito se compilaba y desplegaba en forma independiente. Esto ocasionaba un riesgo alt\xedsimo por falta de acoplamiento o incompatibilidad entre desarrollos, e incluso supresi\xf3n involuntaria de versiones."}),"\n",(0,i.jsx)(a.p,{children:"Ante la aparici\xf3n de integraci\xf3n continua y metodolog\xedas \xe1giles, se nos solicit\xf3 cambiar la forma de trabajo en el equipo, y para esto hab\xeda que readaptar todo nuestro ciclo de vida de software y cambiar nuestras herramientas. El software de control de versi\xf3n se cambiar\xeda por Gitlab y las compilaciones distribuidas se agrupar\xedan en un \xe1rbol de compilaci\xf3n general que asegurase la compatibilidad entre todos los componentes del ecosistema monol\xedtico. Cada componente del ecosistema estaba compilado en un lenguaje distinto, a saber: TAL, C, C++11, Cobol85 y Screen-Cobol. Esto a\xf1ad\xeda una dificultad adicional al problema."}),"\n",(0,i.jsx)(a.p,{children:"Si bien el sistema del Mainframe HPE era propietario y muy espec\xedfico, una de las ventajas que ten\xeda era la posibilidad de interactuar en una parte de todo el sistema con un segundo sistema operativo, s\xedmil Unix. Esto nos prove\xeda de una gama de herramientas adicionales, aunque restringida por la arquitectura de hardware."}),"\n",(0,i.jsx)(a.p,{children:"Tras varias pruebas de concepto, finalmente se concluy\xf3 desarrollar una cadena de sendos scripts en Bash. Su funci\xf3n ser\xeda recopilar todos los makefiles dispersos en el ambiente de desarrollo, los archivos fuentes y las directivas de compilaci\xf3n. La imagen siguiente muestra un resumen de todo el proceso. Cada proceso de script indicado en el diagrama en realidad eran cadenas de scripts m\xe1s espec\xedficos, que utilizaban combinaciones sucesivas de invocaciones a comandos grep, sed, awk y muchas RegEx."}),"\n",(0,i.jsx)(a.p,{children:(0,i.jsx)(a.img,{alt:"Adaptaci\xf3n-Makefiles",src:s(3742).A+"",width:"3236",height:"2912"})})]})}function u(e={}){const{wrapper:a}={...(0,n.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},8453:(e,a,s)=>{s.d(a,{R:()=>r,x:()=>t});var o=s(6540);const i={},n=o.createContext(i);function r(e){const a=o.useContext(n);return o.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(n.Provider,{value:a},e.children)}}}]);